// ═══════════════════════════════════════════════════════════
//  Parse + CRM — Laila V5
//  المهام:
//  1. استخراج بيانات الرسالة
//  2. Guard: fromMe / empty / bot_paused / admin
//  3. حفظ رسالة العميل في conversations
//  4. ACQUIRE LOCK → إذا مقفول → pending_messages → EXIT
//  5. LOAD lead_state أو CREATE جديد
//  6. تحميل chatHistory + managerInstructions
// ═══════════════════════════════════════════════════════════

const SB     = 'https://xfibcjhshpmqkrhlpsoa.supabase.co';
const SB_KEY = 'eyJ-REDACTED-SERVICE-ROLE';
const LOCK_TIMEOUT_S = 30;
const ADMIN_PHONES   = ['380936582617'];

const h = {
  apikey:          SB_KEY,
  Authorization:   'Bearer ' + SB_KEY,
  'Content-Type':  'application/json',
  Prefer:          'return=representation'
};

async function sbGet(path) {
  return this.helpers.httpRequest({ method:'GET', url:`${SB}/rest/v1/${path}`, headers:h });
}
async function sbPost(path, body) {
  return this.helpers.httpRequest({ method:'POST', url:`${SB}/rest/v1/${path}`, headers:h, body });
}
async function sbPatch(path, body) {
  return this.helpers.httpRequest({ method:'PATCH', url:`${SB}/rest/v1/${path}`, headers:h, body });
}
async function sbRpc(fn, body) {
  return this.helpers.httpRequest({ method:'POST', url:`${SB}/rest/v1/rpc/${fn}`, headers:h, body });
}

// ─── Parse Webhook ────────────────────────────────────────
const req  = $input.first().json;
const data = req.data || {};
const key  = data.key  || {};
const msg  = data.message || {};

const phone       = (key.remoteJid || '').replace(/@(s\.whatsapp\.net|c\.us)/, '');
const fromMe      = key.fromMe === true;
const textContent = (
  msg.conversation ||
  msg.extendedTextMessage?.text ||
  msg.text || ''
).trim();
const execId = $execution?.id || ('exec_' + Date.now());

// ─── GUARD 1: fromMe / empty ─────────────────────────────
if (fromMe || !phone || !textContent) {
  return [{ json:{ skip:true, reason:'fromMe_or_empty' } }];
}

// ─── GUARD 2: BOT_PAUSED (من system_config) ──────────────
let botPaused = false;
try {
  const cfg = await sbGet.call(this, 'system_config?key=eq.bot_paused&select=value');
  botPaused  = cfg?.[0]?.value === 'true';
} catch(e) { /* table قد لا تكون موجودة بعد — نكمل */ }

if (botPaused) {
  return [{ json:{ skip:true, reason:'bot_paused', phone,
    pauseResponse:'خدمتنا متوقفة مؤقتاً، سنعود قريباً 🙏' } }];
}

// ─── GUARD 3: Admin Command ──────────────────────────────
const isAdmin   = ADMIN_PHONES.includes(phone);
const isCommand = textContent.startsWith('/');
if (isAdmin && isCommand) {
  return [{ json:{ isAdminCommand:true, phone, textContent, execId } }];
}

// ─── Language detection ───────────────────────────────────
const isArabic = /[\u0600-\u06FF]/.test(textContent);
const language = isArabic ? 'ar' : 'en';

// ─── 1. حفظ رسالة العميل ─────────────────────────────────
try {
  await sbPost.call(this, 'conversations', { phone, role:'user', message:textContent });
} catch(e) {
  console.log('[CRM] save user msg error:', e.message?.slice(0,60));
}

// ─── 2. ACQUIRE LOCK ────────────────────────────────────
let lockAcquired = false;
try {
  const r = await sbRpc.call(this, 'acquire_lead_lock', {
    p_phone: phone, p_holder: execId, p_timeout_s: LOCK_TIMEOUT_S
  });
  lockAcquired = r === true;
  console.log('[LOCK] acquired:', lockAcquired, 'holder:', execId);
} catch(e) {
  console.log('[LOCK] RPC error:', e.message?.slice(0,60));
  lockAcquired = true; // migration غير مكتملة → تابع بدون lock
}

if (!lockAcquired) {
  console.log('[LOCK] LOCKED — queueing:', phone);
  try {
    const lead = await sbGet.call(this, `lead_state?phone=eq.${phone}&is_active=eq.true&select=id`);
    await sbPost.call(this, 'pending_messages', {
      phone,
      lead_id: lead?.[0]?.id || null,
      message: textContent
    });
  } catch(e) {
    console.log('[QUEUE] enqueue error:', e.message?.slice(0,60));
  }
  return [{ json:{ skip:true, reason:'locked', phone } }];
}

// ─── 3. LOAD lead_state ──────────────────────────────────
let lead = null;
try {
  const rows = await sbGet.call(this,
    `lead_state?phone=eq.${phone}&is_active=eq.true&select=*`);
  lead = rows?.[0] || null;
} catch(e) {
  console.log('[LEAD] load error:', e.message?.slice(0,80));
}

// ─── 4. CREATE lead إذا لا يوجد ──────────────────────────
if (!lead) {
  try {
    const now = new Date().toISOString();
    const created = await sbPost.call(this, 'lead_state', {
      phone,
      is_active:     true,
      language,
      status:        'new',
      locked_at:     now,
      lock_holder:   execId,
      first_contact: now,
      last_contact:  now
    });
    lead = created?.[0] || {
      phone, is_active:true, language, status:'new',
      kids_ages:'[]', kids_count:0, offer_count:0, followup_count:0
    };
    console.log('[LEAD] created new:', phone);
  } catch(e) {
    console.log('[LEAD] create error:', e.message?.slice(0,80));
    // fallback in-memory — المحرك سيشتغل بدون DB
    lead = {
      phone, is_active:true, language, status:'new',
      kids_ages:'[]', kids_count:0, offer_count:0, followup_count:0
    };
  }
}

// normalize kids_ages من string لـ array
if (typeof lead.kids_ages === 'string') {
  try { lead.kids_ages = JSON.parse(lead.kids_ages); }
  catch { lead.kids_ages = []; }
}
if (!Array.isArray(lead.kids_ages)) lead.kids_ages = [];

// ─── 5. chatHistory (للـ AI formatter) ───────────────────
let chatHistory = '';
try {
  const msgs = await sbGet.call(this,
    `conversations?phone=eq.${phone}&order=id.asc&limit=30&select=role,message`);
  chatHistory = (msgs || []).map(m =>
    (m.role === 'user' ? 'العميل' : 'ليلى') + ': ' + m.message
  ).join('\n');
} catch(e) { /* اختياري */ }

// ─── 6. Manager instructions ─────────────────────────────
let managerInstructions = '';
try {
  const inst = await sbGet.call(this,
    'manager_instructions?active=eq.true&order=created_at.desc&limit=5&select=instruction');
  if (inst?.length) {
    managerInstructions = inst.map(i => '- ' + i.instruction).join('\n');
  }
} catch(e) { /* اختياري */ }

// ─── Output ──────────────────────────────────────────────
return [{
  json: {
    phone,
    textContent,
    execId,
    isAdmin,
    language,
    lead,            // ← lead state كامل من DB
    chatHistory,
    managerInstructions,
    lockAcquired: true
  }
}];

// ═══════════════════════════════════════════════════════════
//  Decision Engine — Laila V5
//  يُنفَّذ بعد Parse+CRM مباشرة
//  Input:  prev = { phone, textContent, execId, lead, chatHistory, ... }
//  Output: { ...prev, response, action, newLeadState }
// ═══════════════════════════════════════════════════════════

// ─── Config ───────────────────────────────────────────────
const CONFIG = {
  SESSION_RESET_GAP_H: 4,
  FOLLOWUP_DELAY_H:    3,
  LOCK_TIMEOUT_S:      30,
  SUPPORT_LINK:        'https://wa.me/380936582617',
};

const DESTINATIONS = {
  KZ: { is_active:true,  pricing_ready:true,  flag:'🇰🇿', label:'كازاخستان',
        cities:['Almaty','resort'], multi_city:true,
        city_q:'تفضلون ألماتي أو تحبون نضيف المنتجع للبرنامج؟' },
  RU: { is_active:true,  pricing_ready:true,  flag:'🇷🇺', label:'روسيا',
        cities:['Moscow','Saint Petersburg'], multi_city:true,
        city_q:'تفضلون موسكو أو سانت بطرسبرغ، أو تحبون المدينتين؟' },
  PL: { is_active:true,  pricing_ready:false, flag:'🇵🇱', label:'بولندا',
        cities:['Warsaw'], multi_city:false, city_q:null,
        manual_msg:'شكراً! استلمنا طلبك لبولندا. فريقنا سيتواصل خلال 24 ساعة 🙏' },
  UZ: { is_active:true,  pricing_ready:false, flag:'🇺🇿', label:'أوزبكستان',
        cities:['Tashkent'], multi_city:false, city_q:null,
        manual_msg:'شكراً! استلمنا طلبك لأوزبكستان. فريقنا سيتواصل خلال 24 ساعة 🙏' },
};

const PE_URL = 'https://n8n.arcadia-tour.cloud/webhook/pricing-engine';

// ─── Helpers ─────────────────────────────────────────────
const now  = () => new Date().toISOString();
const addH = (h) => new Date(Date.now() + h * 3600000).toISOString();
const hoursSince = (ts) => ts ? (Date.now() - new Date(ts).getTime()) / 3600000 : 999;

function extractFromMsg(msg) {
  const ex = {};

  // dest
  if (/كازاخستان|kazakhstan/i.test(msg)) ex.dest = 'KZ';
  else if (/روسيا|russia/i.test(msg))    ex.dest = 'RU';
  else if (/بولندا|poland/i.test(msg))   ex.dest = 'PL';
  else if (/أوزبكستان|uzbekistan/i.test(msg)) ex.dest = 'UZ';

  // city KZ
  if (/ألماتي|الماتي|almaty/i.test(msg))         ex.city = 'Almaty';
  else if (/منتجع|أكواخ|أوي قورقاي/i.test(msg))  ex.city = 'resort';
  // city RU
  else if (/موسكو|moscow/i.test(msg))             ex.city = 'Moscow';
  else if (/سانت|saint|بطرسبرغ/i.test(msg))      ex.city = 'Saint Petersburg';

  // multi-city
  if (/المدينتين|كلاهما|موسكو.{1,15}سانت|سانت.{1,15}موسكو/i.test(msg)) {
    ex.multi_city = true;
    ex.city       = 'multi';
  }
  if (/ألماتي.{1,15}منتجع|منتجع.{1,15}ألماتي/i.test(msg)) {
    ex.multi_city = true;
    ex.city       = 'multi';
  }

  // nights
  const nightsM = msg.match(/(\d+)\s*(?:ليالٍ|ليالي|ليلة)/);
  if (nightsM) ex.nights = parseInt(nightsM[1]);
  else {
    const daysM = msg.match(/(\d+)\s*(?:يوم|أيام)/);
    if (daysM) ex.nights = parseInt(daysM[1]) - 1;
  }

  // adults
  if (/شخصين/i.test(msg))              ex.adults = 2;
  else if (/شخص واحد|شخص فقط/i.test(msg)) ex.adults = 1;
  else {
    const aM = msg.match(/(\d+)\s*(?:أشخاص|شخص|بالغين|بالغ)/);
    if (aM) ex.adults = parseInt(aM[1]);
  }

  // kids
  const kM = msg.match(/(\d+)\s*(?:طفل|أطفال)/);
  if (kM) ex.kids_count = parseInt(kM[1]);

  // kids ages
  const ages = [];
  const a1 = msg.matchAll(/(\d+)\s*(?:سنة|سنوات|عام)/g);
  for (const m of a1) { const n=parseInt(m[1]); if(n>0&&n<18) ages.push(n); }
  if (ages.length) ex.kids_ages = [...new Set(ages)];

  return ex;
}

function applyExtracted(lead, ex) {
  if (ex.dest)      lead.dest      = ex.dest;
  if (ex.city)      lead.city      = ex.city;
  if (ex.nights)    lead.nights    = ex.nights;
  if (ex.adults)    lead.adults    = ex.adults;
  if (ex.kids_count) lead.kids_count = ex.kids_count;
  if (ex.kids_ages?.length) lead.kids_ages = ex.kids_ages;
  if (ex.multi_city) { lead.multi_city = true; }
}

function clearDoneAwaiting(lead) {
  const aw = lead.awaiting_field;
  if (aw === 'dest'      && lead.dest)   lead.awaiting_field = null;
  if (aw === 'city'      && lead.city)   lead.awaiting_field = null;
  if (aw === 'nights'    && lead.nights) lead.awaiting_field = null;
  if (aw === 'adults'    && lead.adults) lead.awaiting_field = null;
  if (aw === 'kids_ages' && lead.kids_ages.length >= lead.kids_count)
                                         lead.awaiting_field = null;
}

function clearLeadFields(lead, fields) {
  const nulls = { dest:null, city:null, nights:null, adults:null,
                  kids_count:0, kids_ages:[], multi_city:false, segments:null,
                  last_offer:null, awaiting_field:null, next_followup_at:null,
                  last_handoff_reason:null, handoff_at:null };
  for (const f of fields) { if (f in nulls) lead[f] = nulls[f]; }
}

function detectIntent(msg) {
  if (/\b(نعم|أحجز|أكيد|تمام|موافق|confirm|book|أبي أحجز)\b/i.test(msg))
    return 'confirm';
  if (/غالي|أرخص|أقل|مو مناسب|expensive|cheaper|وفر/i.test(msg))
    return 'too_expensive';
  if (/خيار ثاني|فندق ثاني|غير الفندق|بديل|alternative|other hotel/i.test(msg))
    return 'alternative';
  if (/مو مهتم|مو محتاج|إلغاء|cancel|لاحقاً|وقت آخر/i.test(msg))
    return 'not_interested';
  return 'other';
}

function parseAltType(msg) {
  if (/نفس|مشابه|same|similar/i.test(msg))                   return 'same_tier';
  if (/أعلى|أفخم|luxury|upgrade|5 نجوم|فخم/i.test(msg))     return 'upgrade';
  if (/أقل|أرخص|أبسط|downgrade|3 نجوم|اقتصادي/i.test(msg)) return 'downgrade';
  return 'unclear';
}

function getMinTier(packages) {
  if (!packages?.length) return null;
  const order = ['economy','silver','gold'];
  const tiers = packages.map(p => p.tierAr || p.tier || '').map(t =>
    t.includes('اقتصادي') ? 'economy' : t.includes('فضي') ? 'silver' : 'gold');
  return tiers.sort((a,b) => order.indexOf(a)-order.indexOf(b))[0];
}

function buildHotelLink(lead) {
  const hotels = lead.last_offer?.packages?.map(p=>p.hotelName).filter(Boolean);
  if (!hotels?.length)
    return 'أرسل لنا أولاً تفاصيل الرحلة وسنرسل معلومات الفندق 🏨';
  return hotels.map(n => {
    const q = encodeURIComponent(n + ' hotel');
    return `🏨 *${n}*\n🔗 https://www.google.com/search?q=${q}`;
  }).join('\n\n') + '\n\n_للحجز تواصل معنا مباشرة_';
}

function buildCloseMsg() {
  return `ممتاز! 🎉 للتأكيد والدفع تواصل مع فريقنا مباشرة:\n${CONFIG.SUPPORT_LINK}\nنتطلع لخدمتكم!`;
}

function buildNudge(lead) {
  const dest = DESTINATIONS[lead.dest]?.label || 'الوجهة';
  return `الباقة متاحة الآن. لا تتأخرون حتى لا تُحجز الأماكن 🔥\nتحبون نثبت رحلتكم إلى ${dest}؟`;
}

function buildUrgencyNudge(lead) {
  return `نعرف الأسعار مهمة. هذا أفضل سعر عندنا لهذه المواصفات.\nتحبون نساعدكم بخيار يناسبكم أكثر؟`;
}

function formatPackages(pkgs, lead, opts={}) {
  const dest = DESTINATIONS[lead.dest];
  const TIERS = { 0:'🥉 اقتصادية', 1:'🥈 فضية', 2:'🥇 ذهبية' };
  const prefix = opts.prefix || `عندي لكم 3 باقات شاملة لـ${dest?.label||''} ${dest?.flag||''} — ${lead.nights} ليالٍ:\n`;
  const lines = pkgs.slice(0,3).map((p,i) => {
    const tier = TIERS[i] || TIERS[2];
    return `*${tier}*\n- فندق: ${p.hotelName} ${'⭐'.repeat(p.stars||4)}\n- ${p.roomType||'غرفة مزدوجة'}\n- ${p.mealPlan||'إفطار يومي'}\n- السعر: *$${p.totalUSD?.toLocaleString()}*`;
  }).join('\n\n');
  return prefix + lines + '\n\nأي باقة يناسبكم أكثر؟ 😊';
}

// ─── PE Call ─────────────────────────────────────────────
async function callPE(body) {
  try {
    const r = await this.helpers.httpRequest({ method:'POST', url:PE_URL,
      headers:{'Content-Type':'application/json'}, body });
    if (r.ok || r.packages?.length) return r;
    return { ok:false, noMore: r.noMore || false };
  } catch(e) {
    console.log('[PE] error:', e.message?.slice(0,80));
    return { ok:false, noMore:false };
  }
}

function buildPEInput(lead, opts={}) {
  if (lead.multi_city && lead.dest==='RU') {
    return { destination:'RU', adults:lead.adults,
      segments:[{city:'Moscow',nights:Math.ceil(lead.nights/2)},
                {city:'Saint Petersburg',nights:Math.floor(lead.nights/2)}],
      childrenAges: lead.kids_ages?.length ? lead.kids_ages : undefined };
  }
  if (lead.multi_city && lead.dest==='KZ') {
    return { destination:'KZ', adults:lead.adults,
      segments:[{city:'Almaty',nights:Math.ceil(lead.nights/2)},
                {city:'resort',nights:Math.floor(lead.nights/2)}],
      childrenAges: lead.kids_ages?.length ? lead.kids_ages : undefined };
  }
  const body = {
    destination:   lead.dest,
    city:          lead.city === 'resort' ? 'Almaty' : lead.city,
    nights:        lead.nights,
    adults:        lead.adults,
    childrenAges:  lead.kids_ages?.length ? lead.kids_ages : undefined,
    resort:        lead.city === 'resort' ? true : undefined,
    withGuide:     false,
  };
  if (opts.exclude)      body.exclude      = opts.exclude;
  if (opts.maxTierBelow) body.maxTierBelow = opts.maxTierBelow;
  return body;
}

// ─── Main Flow ────────────────────────────────────────────
const prev = $input.first().json;

// skip من Parse+CRM
if (prev.skip) return [{ json:prev }];

// admin command → سيُعالَج في node منفصل
if (prev.isAdminCommand) return [{ json:prev }];

const { phone, textContent: msg, execId, language } = prev;
let lead = { ...prev.lead };

// ═══ STEP 1: MERGE + CLEAR ═══════════════════════════════
const ex = extractFromMsg(msg);
applyExtracted(lead, ex);
clearDoneAwaiting(lead);

// ✅ احسب gap من القيمة القديمة قبل أي تحديث
const gapH = hoursSince(lead.last_contact);

// تحديث timestamps
lead.last_user_message_at = now();
lead.last_contact         = now();

// ═══ STEP 2: SESSION RESET ═══════════════════════════════
const isGreeting = /السلام|هلا|مرحبا|صباح|مساء|hi\b|hello/i.test(msg);
const newTrip    = /وجهة جديدة|رحلة ثانية|سفرة ثانية|رحلة مختلفة/i.test(msg);
const activeS    = ['quoted','interested','followup'].includes(lead.status);
const closedS    = ['closed','lost'].includes(lead.status);

// Re-entry لـ closed/lost
if (closedS && ((isGreeting && gapH > CONFIG.SESSION_RESET_GAP_H) || newTrip)) {
  clearLeadFields(lead, ['dest','city','nights','adults','kids_count','kids_ages',
    'multi_city','segments','last_offer','awaiting_field','next_followup_at',
    'last_handoff_reason','handoff_at']);
  lead.status        = 'collecting_info';
  lead.awaiting_field = null;
  const replyMsg = lead.status==='closed'
    ? 'يا هلا، أهلاً بك مرة ثانية! 😊 وجهتكم هالمرة وين؟'
    : 'يا هلا! وجهتكم وين؟ 🌍';
  return [{ json:{ ...prev, lead, response:replyMsg, action:'session_reset',
    newLeadState:{ ...lead, last_action:'session_reset' } } }];
}

// closed/lost بدون re-entry intent
if (closedS) {
  if (lead.status === 'closed') {
    return [{ json:{ ...prev, lead, response:'شكراً لتواصلك! إذا أردت رحلة جديدة نحن هنا 🙏',
      action:'closed_noop', newLeadState:{ ...lead, last_action:'closed_noop' } } }];
  }
  return [{ json:{ ...prev, lead, skip:true, reason:'lost_silence' } }];
}

// Active session reset
if (activeS && ((isGreeting && gapH > CONFIG.SESSION_RESET_GAP_H) || newTrip)) {
  clearLeadFields(lead, ['dest','city','nights','adults','kids_count','kids_ages',
    'multi_city','segments','last_offer','awaiting_field','next_followup_at']);
  lead.status = 'collecting_info';
  return [{ json:{ ...prev, lead, response:'يا هلا! وجهتكم الجديدة وين؟ 🌍',
    action:'session_reset', newLeadState:{ ...lead, last_action:'session_reset' } } }];
}

// ═══ STEP 3: INTENT GATE (أولوية عالية) ══════════════════
// إذا طلب برنامج سياحي
if (/برنامج|جدول الرحلة|خطة السفر|itinerary|schedule/i.test(msg)) {
  return [{ json:{ ...prev, lead, action:'send_itinerary',
    newLeadState:{ ...lead, last_action:'send_itinerary' } } }];
  // يُعالَج في Itinerary node منفصل
}

// إذا طلب رابط/صورة فندق
if (/صور الفندق|رابط الفندق|موقع الفندق|لينك الفندق|hotel link|hotel photo/i.test(msg)) {
  const linkResp = buildHotelLink(lead);
  return [{ json:{ ...prev, lead, response:linkResp, action:'send_hotel_link',
    newLeadState:{ ...lead, last_action:'send_hotel_link' } } }];
}

// ═══ STEP 4: DEST CONFIG GATE ════════════════════════════
if (lead.dest) {
  const cfg = DESTINATIONS[lead.dest];
  if (!cfg || !cfg.is_active) {
    const resp = 'للأسف ما عندنا رحلات لهذه الوجهة حالياً.\nعندنا: كازاخستان 🇰🇿، روسيا 🇷🇺، بولندا 🇵🇱 — أيها يناسبك؟';
    return [{ json:{ ...prev, lead, response:resp, action:'dest_not_available',
      newLeadState:{ ...lead, last_action:'dest_not_available' } } }];
  }
}

// ═══ STEP 5: DECISION ENGINE (status-based) ══════════════
const status = (lead.status === 'new') ? 'collecting_info' : lead.status;

// ────────────────── collecting_info ──────────────────────
if (status === 'collecting_info') {

  if (lead.status === 'new') lead.status = 'collecting_info';

  // pricing_ready=false → جمع البيانات → manual_quote
  const cfg = lead.dest ? DESTINATIONS[lead.dest] : null;
  if (cfg && !cfg.pricing_ready && lead.nights && lead.adults) {
    return [{ json:{ ...prev, lead, response: cfg.manual_msg,
      action:'manual_quote', newLeadState:{ ...lead, status:'manual_quote',
        awaiting_field:null, last_action:'manual_quote' } } }];
  }

  // FIELDS GATE
  if (!lead.dest) {
    return [{ json:{ ...prev, lead, response:'وين تحبون تسافرون؟ 🌍',
      action:'ask_dest', newLeadState:{ ...lead, status:'collecting_info',
        awaiting_field:'dest', last_action:'ask_dest' } } }];
  }

  const destCfg = DESTINATIONS[lead.dest];

  // multi-city gate
  if (lead.multi_city) {
    if (!lead.nights) {
      return [{ json:{ ...prev, lead, response:'كم ليلة إجمالي للرحلة؟',
        action:'ask_nights', newLeadState:{ ...lead, awaiting_field:'nights', last_action:'ask_nights' } } }];
    }
  } else {
    // single city gate
    if (!lead.city && destCfg?.cities?.length > 1) {
      return [{ json:{ ...prev, lead, response: destCfg.city_q,
        action:'ask_city', newLeadState:{ ...lead, awaiting_field:'city', last_action:'ask_city' } } }];
    }
    if (!lead.city && destCfg?.cities?.length === 1) {
      lead.city = destCfg.cities[0]; // auto-fill
    }
  }

  if (!lead.nights) {
    return [{ json:{ ...prev, lead, response:'كم ليلة تودون تقضون؟',
      action:'ask_nights', newLeadState:{ ...lead, awaiting_field:'nights', last_action:'ask_nights' } } }];
  }

  if (!lead.adults) {
    return [{ json:{ ...prev, lead, response:'كم عدد الأشخاص البالغين؟',
      action:'ask_adults', newLeadState:{ ...lead, awaiting_field:'adults', last_action:'ask_adults' } } }];
  }

  if (lead.kids_count > 0 && lead.kids_ages.length < lead.kids_count) {
    const miss = lead.kids_count - lead.kids_ages.length;
    const q = miss === lead.kids_count ? 'ما أعمار الأطفال؟' : `ما أعمار باقي الأطفال الـ${miss}؟`;
    return [{ json:{ ...prev, lead, response:q,
      action:'ask_kids_ages', newLeadState:{ ...lead, awaiting_field:'kids_ages', last_action:'ask_kids_ages' } } }];
  }

  // ── كل الحقول مكتملة → PE CALL ──
  const peInput  = buildPEInput(lead);
  const peResult = await callPE.call(this, peInput);
  console.log('[PE] result:', JSON.stringify(peResult).slice(0,200));

  if (!peResult.ok && peResult.noMore) {
    return [{ json:{ ...prev, lead, response:`ما في خيارات لهذه المواصفات. تواصل مع فريقنا: ${CONFIG.SUPPORT_LINK}`,
      action:'no_options', newLeadState:{ ...lead, last_action:'no_options' } } }];
  }
  if (!peResult.ok || !peResult.packages?.length) {
    return [{ json:{ ...prev, lead, response:'فيه مشكلة تقنية، جرب مرة ثانية.',
      action:'pe_error', newLeadState:{ ...lead, last_action:'pe_error' } } }];
  }

  const resp = formatPackages(peResult.packages, lead);
  return [{ json:{ ...prev, lead, response:resp, action:'quote',
    newLeadState:{ ...lead, status:'quoted', awaiting_field:'confirmation',
      next_followup_at: addH(CONFIG.FOLLOWUP_DELAY_H),
      last_offer:{ packages:peResult.packages, pe_input:peInput, sent_at:now() },
      offer_count:(lead.offer_count||0)+1, last_action:'quoted' } } }];
}

// ────────────────── quoted ───────────────────────────────
if (status === 'quoted') {

  // alternative choice parser
  if (lead.awaiting_field === 'alternative_choice') {
    const altType = parseAltType(msg);
    if (altType === 'unclear') {
      return [{ json:{ ...prev, lead, response:'تبي نفس الفئة، أو فندق أعلى، أو أقل؟',
        action:'alternative_ask', newLeadState:{ ...lead, awaiting_field:'alternative_choice' } } }];
    }
    const lastHotel = lead.last_offer?.packages?.at(-1)?.hotelName;
    const peInput   = buildPEInput(lead, {
      exclude:      lastHotel,
      maxTierBelow: altType === 'downgrade' ? getMinTier(lead.last_offer?.packages) : undefined,
      upgrade:      altType === 'upgrade'
    });
    const peRes = await callPE.call(this, peInput);
    if (!peRes.ok || peRes.noMore) {
      return [{ json:{ ...prev, lead, response:`ما في بديل لهذا الخيار. ${CONFIG.SUPPORT_LINK}`,
        action:'no_options', newLeadState:{ ...lead, awaiting_field:'confirmation', last_action:'no_options' } } }];
    }
    const resp = formatPackages(peRes.packages, lead, { prefix:'تفضل الخيار البديل:\n' });
    return [{ json:{ ...prev, lead, response:resp, action:`alternative_${altType}`,
      newLeadState:{ ...lead, last_offer:{ packages:peRes.packages, pe_input:peInput, sent_at:now() },
        offer_count:(lead.offer_count||0)+1, awaiting_field:'confirmation',
        last_action:`alternative_${altType}` } } }];
  }

  const intent = detectIntent(msg);

  if (intent === 'confirm') {
    return [{ json:{ ...prev, lead, response:buildCloseMsg(), action:'close',
      newLeadState:{ ...lead, status:'closed', awaiting_field:null, last_action:'closed_by_user',
        last_user_intent:'confirm' } } }];
  }

  if (intent === 'too_expensive') {
    const curMinTier = getMinTier(lead.last_offer?.packages);
    const peInput    = buildPEInput(lead, {
      exclude:      lead.last_offer?.packages?.at(-1)?.hotelName,
      maxTierBelow: curMinTier
    });
    const peRes = await callPE.call(this, peInput);
    if (!peRes.ok || peRes.noMore) {
      return [{ json:{ ...prev, lead,
        response:'هذا أفضل سعر متاح عندنا. تحب نعدّل عدد الليالي؟',
        action:'no_cheaper', newLeadState:{ ...lead, status:'interested', last_user_intent:'price_objection' } } }];
    }
    const resp = formatPackages(peRes.packages, lead, { prefix:'عندي خيار أوفر:\n' });
    return [{ json:{ ...prev, lead, response:resp, action:'requote_cheaper',
      newLeadState:{ ...lead, status:'interested', awaiting_field:'confirmation',
        last_offer:{ packages:peRes.packages, pe_input:peInput, sent_at:now() },
        offer_count:(lead.offer_count||0)+1, last_user_intent:'price_objection',
        last_action:'requote_cheaper' } } }];
  }

  if (intent === 'alternative') {
    return [{ json:{ ...prev, lead,
      response:'وش اللي تدور فيه؟ فندق ثاني بنفس الفئة، أو أعلى، أو أقل؟',
      action:'alternative_ask', newLeadState:{ ...lead, awaiting_field:'alternative_choice',
        last_user_intent:'alternative', last_action:'ask_alternative' } } }];
  }

  return [{ json:{ ...prev, lead, response:buildNudge(lead), action:'sales_nudge',
    newLeadState:{ ...lead, last_action:'sales_nudge' } } }];
}

// ────────────────── interested ───────────────────────────
if (status === 'interested') {
  const intent = detectIntent(msg);

  if (intent === 'confirm') {
    return [{ json:{ ...prev, lead, response:buildCloseMsg(), action:'close',
      newLeadState:{ ...lead, status:'closed', awaiting_field:null,
        last_action:'closed_by_user', last_user_intent:'confirm' } } }];
  }

  if (intent === 'not_interested') {
    return [{ json:{ ...prev, lead,
      response:'شكراً لتواصلك! إذا غيرت رأيك أو احتجت مساعدة نحن هنا 🙏',
      action:'lost', newLeadState:{ ...lead, status:'lost', last_action:'lost' } } }];
  }

  if (intent === 'too_expensive' || intent === 'alternative') {
    if ((lead.offer_count||0) >= 2) {
      return [{ json:{ ...prev, lead,
        response:`فريقنا قد يملك حلولاً أخرى. تواصل معنا: ${CONFIG.SUPPORT_LINK}`,
        action:'handoff_to_human', newLeadState:{ ...lead, status:'handoff',
          last_handoff_reason:'price_limit_reached', handoff_at:now(), last_action:'handoff' } } }];
    }
    const peInput = buildPEInput(lead, { maxTierBelow: getMinTier(lead.last_offer?.packages) });
    const peRes   = await callPE.call(this, peInput);
    if (!peRes.ok || peRes.noMore) {
      return [{ json:{ ...prev, lead,
        response:`ما في خيار أوفر. فريقنا يساعدك: ${CONFIG.SUPPORT_LINK}`,
        action:'handoff_to_human', newLeadState:{ ...lead, status:'handoff',
          last_handoff_reason:'no_cheaper_options', handoff_at:now() } } }];
    }
    const resp = formatPackages(peRes.packages, lead, { prefix:'آخر خيار عندي:\n' });
    return [{ json:{ ...prev, lead, response:resp, action:'requote_cheaper',
      newLeadState:{ ...lead, awaiting_field:'confirmation',
        last_offer:{ packages:peRes.packages, pe_input:peInput, sent_at:now() },
        offer_count:(lead.offer_count||0)+1, last_action:'requote_cheaper' } } }];
  }

  return [{ json:{ ...prev, lead, response:buildUrgencyNudge(lead), action:'sales_nudge',
    newLeadState:{ ...lead, last_action:'urgency_nudge' } } }];
}

// ────────────────── followup ─────────────────────────────
if (status === 'followup') {
  const intent = detectIntent(msg);
  if (intent === 'confirm') {
    return [{ json:{ ...prev, lead, response:buildCloseMsg(), action:'close',
      newLeadState:{ ...lead, status:'closed', awaiting_field:null } } }];
  }
  if (intent === 'not_interested') {
    return [{ json:{ ...prev, lead,
      response:'شكراً لتواصلك! إذا احتجتنا في أي وقت نحن هنا 🙏',
      action:'lost', newLeadState:{ ...lead, status:'lost' } } }];
  }
  // عودة إيجابية → أعد تفعيل
  const offerSummary = lead.last_offer?.packages?.[0]
    ? `${lead.last_offer.packages[0].hotelName} من $${lead.last_offer.packages[0].totalUSD}`
    : 'عرضنا السابق';
  return [{ json:{ ...prev, lead,
    response:`يا هلا! ${offerSummary} — هل تودون نكمل؟`,
    action:'reactivate', newLeadState:{ ...lead, status:'interested', awaiting_field:'confirmation' } } }];
}

// ────────────────── manual_quote ─────────────────────────
if (status === 'manual_quote') {
  return [{ json:{ ...prev, lead,
    response:'فريقنا سيتواصل معك قريباً. إذا عندك تفاصيل إضافية أرسلها هنا 🙏',
    action:'manual_followup', newLeadState:{ ...lead, last_action:'manual_followup' } } }];
}

// ────────────────── handoff ──────────────────────────────
if (status === 'handoff') {
  const isNewReq = /وجهة|سعر|بكج|أبي أروح|رحلة|أسعار/i.test(msg);
  if (isNewReq) {
    clearLeadFields(lead, ['dest','city','nights','adults','kids_count','kids_ages',
      'multi_city','segments','last_offer','awaiting_field','next_followup_at',
      'last_handoff_reason','handoff_at']);
    lead.status = 'collecting_info';
    return [{ json:{ ...prev, lead, response:'يا هلا! وجهتكم وين؟ 🌍',
      action:'session_reset', newLeadState:{ ...lead, last_action:'session_reset' } } }];
  }
  return [{ json:{ ...prev, lead,
    response:`فريقنا سيتواصل معك. للاستفسار المباشر: ${CONFIG.SUPPORT_LINK}`,
    action:'handoff_reassure', newLeadState:{ ...lead, last_action:'handoff_reassure' } } }];
}

// ─── Fallback (status غير متوقع) ─────────────────────────
return [{ json:{ ...prev, lead,
  response:'يا هلا! كيف أقدر أساعدك؟ 😊',
  action:'fallback', newLeadState:{ ...lead, status:'collecting_info',
    awaiting_field:null, last_action:'fallback' } } }];

// ═══════════════════════════════════════════════════════════
//  Save + Unlock — Laila V5
//  الترتيب الصحيح:
//  1. إرسال WhatsApp (في Send WhatsApp node منفصل)
//  2. حفظ رسالة البوت في conversations
//  3. حفظ lead_state + RELEASE LOCK (PATCH واحد)
//  4. معالجة pending_messages
// ═══════════════════════════════════════════════════════════

const SB     = 'https://xfibcjhshpmqkrhlpsoa.supabase.co';
const SB_KEY = 'eyJ-REDACTED-SERVICE-ROLE';

const h = {
  apikey: SB_KEY, Authorization:`Bearer ${SB_KEY}`,
  'Content-Type':'application/json', Prefer:'return=representation'
};

const prev = $input.first().json;

// skip / silence
if (prev.skip || !prev.response || prev.reason === 'lost_silence') {
  // حتى في skip: RELEASE LOCK إذا كان مقفولاً
  if (prev.execId && prev.phone && prev.lockAcquired) {
    try {
      await this.helpers.httpRequest({ method:'POST',
        url:`${SB}/rest/v1/rpc/release_lead_lock`, headers:h,
        body:{ p_phone:prev.phone, p_holder:prev.execId } });
    } catch(_) {}
  }
  return [{ json: prev }];
}

const { phone, execId, response, lead, newLeadState, action } = prev;

let saveOk  = false;
let stateOk = false;

try {
  // ── 1. حفظ رسالة البوت في conversations ──────────────
  await this.helpers.httpRequest({ method:'POST',
    url:`${SB}/rest/v1/conversations`, headers:h,
    body:{ phone, role:'assistant', message:response } });
  saveOk = true;

  // ── 2. حفظ lead_state + RELEASE LOCK في PATCH واحد ──
  if (newLeadState?.id) {
    const patchBody = {
      ...newLeadState,
      last_bot_message_at: new Date().toISOString(),
      updated_at:          new Date().toISOString(),
      locked_at:           null,   // ← RELEASE LOCK
      lock_holder:         null
    };
    // إزالة حقول غير قابلة للـ PATCH
    delete patchBody.id;
    delete patchBody.created_at;
    delete patchBody.first_contact;

    await this.helpers.httpRequest({ method:'PATCH',
      url:`${SB}/rest/v1/lead_state?id=eq.${newLeadState.id}`,
      headers:h, body: patchBody });
    stateOk = true;
    console.log(`[SAVE] action=${action} status=${newLeadState.status} awaiting=${newLeadState.awaiting_field}`);
  } else {
    // لا يوجد id (in-memory lead فقط) → فك القفل بـ RPC
    await this.helpers.httpRequest({ method:'POST',
      url:`${SB}/rest/v1/rpc/release_lead_lock`, headers:h,
      body:{ p_phone:phone, p_holder:execId } });
    stateOk = true;
  }

} catch(err) {
  console.log(`[SAVE ERROR] action=${action} save=${saveOk} state=${stateOk}:`, err.message?.slice(0,80));

  // ─── send_failed: سجّل الخطأ على الـ lead + unlock ──
  try {
    const patchErr = {
      last_action:  (action||'') + '_save_failed',
      locked_at:    null,
      lock_holder:  null,
      updated_at:   new Date().toISOString()
    };
    if (newLeadState?.id) {
      await this.helpers.httpRequest({ method:'PATCH',
        url:`${SB}/rest/v1/lead_state?id=eq.${newLeadState.id}`,
        headers:h, body: patchErr });
    }
  } catch(e2) {
    // worst case → RPC release
    try {
      await this.helpers.httpRequest({ method:'POST',
        url:`${SB}/rest/v1/rpc/release_lead_lock`, headers:h,
        body:{ p_phone:phone, p_holder:execId } });
    } catch(_) {}
  }
} finally {
  // ضمان نهائي: إذا فشل كل شيء → force release بـ RPC
  if (!stateOk && execId && phone) {
    try {
      await this.helpers.httpRequest({ method:'POST',
        url:`${SB}/rest/v1/rpc/release_lead_lock`, headers:h,
        body:{ p_phone:phone, p_holder:execId } });
    } catch(_) {}
  }
}

// ── 3. معالجة pending_messages بعد unlock ────────────────
try {
  const pending = await this.helpers.httpRequest({ method:'GET',
    url:`${SB}/rest/v1/pending_messages?phone=eq.${phone}&processed=eq.false&order=received_at.asc&limit=1`,
    headers:h });

  if (pending?.length > 0) {
    const pm = pending[0];
    console.log('[QUEUE] processing pending:', pm.id, pm.message?.slice(0,30));

    // mark attempt
    await this.helpers.httpRequest({ method:'PATCH',
      url:`${SB}/rest/v1/pending_messages?id=eq.${pm.id}`,
      headers:h, body:{ attempt_count:(pm.attempt_count||0)+1 } });

    // re-trigger webhook
    try {
      await this.helpers.httpRequest({ method:'POST',
        url:'https://n8n.arcadia-tour.cloud/webhook/laila-v5',
        headers:{'Content-Type':'application/json'},
        body:{ data:{ key:{ remoteJid:`${phone}@s.whatsapp.net`, fromMe:false },
                      message:{ conversation: pm.message },
                      messageType:'conversation' },
               _pending_id: pm.id } });

      await this.helpers.httpRequest({ method:'PATCH',
        url:`${SB}/rest/v1/pending_messages?id=eq.${pm.id}`,
        headers:h, body:{ processed:true, processed_at:new Date().toISOString() } });
      console.log('[QUEUE] dequeued ok:', pm.id);
    } catch(e) {
      await this.helpers.httpRequest({ method:'PATCH',
        url:`${SB}/rest/v1/pending_messages?id=eq.${pm.id}`,
        headers:h, body:{ error_text: e.message?.slice(0,200) } });
    }
  }
} catch(e) {
  console.log('[QUEUE] check error:', e.message?.slice(0,60));
}

return [{ json:{ ...prev, saveOk, stateOk } }];
